window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7e94b1abe7e05b71"]={"versions": [{"id": "FIG-7e94b1abe7e05b71", "releases": ["R21-11", "R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (ab Release R21-11), Spezifikation <code>AUTOSAR_CP_SWS_MemoryAccess</code> (<code>MemAcc</code>).\n</li><li><strong>Funktionale Einordnung:</strong> Kaskadierte Treiberinitialisierung im modernisierten AUTOSAR-Memory-Stack. Das Modul <code>MemAcc</code> kapselt den Zugriff auf hardwarenahe Speichertreiber (<code>Mem</code>-Treiber für Flash/EEPROM) und übernimmt bei dieser Architekturvariante die koordinierte Initialisierung der unterlagerten MCAL-Treiberinstanzen, wodurch der <code>EcuM</code> von der Einzelansteuerung entlastet wird.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Beteiligte Instanzen (<code>«module»</code>):</strong>\n<ul class=\"fig-list\"><li><code>:EcuM</code> (ECU State Manager, BSW System Services): Initiator der BSW-Initialisierungsphasen (z. B. StartOS/Post-OS bzw. EcuM Driver Init Block).\n</li><li><code>:MemAcc</code> (Memory Access Module, BSW Memory Abstraction/Service Layer): Zentraler Vermittler und Scheduler für Speicheraufträge; orchestriert die unterlagerten Treiber.\n</li><li><code>:Mem</code> (Memory Driver, BSW MCAL): Repräsentiert die konkreten Hardware-Treiberinstanzen gemäß <code>AUTOSAR_CP_SWS_MemoryDriver</code>. Im Diagramm differenziert über Vendor- und API-Infixes:\n<ul class=\"fig-list\"><li>Program Flash Driver: Infix <code>30_PFls</code> (Vendor-ID <code>30</code>, Program Flash).\n</li><li>Data Flash Driver: Infix <code>30_DFls</code> (Vendor-ID <code>30</code>, Data Flash).\n</li></ul>\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Signaturen:</strong>\n<ul class=\"fig-list\"><li><code>MemAcc_Init(const MemAcc_ConfigType* ConfigPtr)</code>: Globale Initialisierungs-API des <code>MemAcc</code>.\n</li><li><code>Mem_30_PFls_Init(const Mem_30_PFls_ConfigType* ConfigPtr)</code>: Treiber-Initialisierung für Program-Flash-Controller.\n</li><li><code>Mem_30_DFls_Init(const Mem_30_DFls_ConfigType* ConfigPtr)</code>: Treiber-Initialisierung für Data-Flash-Controller.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Trigger:</strong> <code>:EcuM</code> führt den synchronen Aufruf <code>MemAcc_Init()</code> aus.\n</li><li><strong>Kaskadierte Treiber-Initialisierung (sequenziell, blockierend):</strong>\n<ul class=\"fig-list\"><li><code>:MemAcc</code> ruft synchron <code>Mem_30_PFls_Init()</code> auf. Der Program-Flash-Treiber initialisiert Controller-Register, Verifikationszustände und Adressmappings; die Ausführung kehrt synchron zu <code>:MemAcc</code> zurück.\n</li><li><code>:MemAcc</code> ruft unmittelbar danach synchron <code>Mem_30_DFls_Init()</code> auf. Der Data-Flash-Treiber schließt die Hardwarekonfiguration ab und kehrt synchron zurück.\n</li></ul>\n</li><li><strong>Abschluss:</strong> Nach erfolgreicher Registrierung und Initialisierung aller im <code>MemAcc</code>-Konfigurationssatz referenzierten Treiber kehrt <code>MemAcc_Init()</code> zum <code>:EcuM</code> zurück.\n</li></ol>\n<ul class=\"fig-list\"><li><strong>Asynchronität / Callbacks:</strong> Keine asynchronen Pfade oder OS-Callbacks im gezeigten Pfad. Das Fehlerhandling (z. B. <code>MemAcc_Init()</code> bei ungültiger Konfiguration via <code>DET</code>) ist im Gutfall-Diagramm abstrahiert.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>EcuM-Konfiguration:</strong> In der BSW-Initialisierungstabelle des <code>EcuM</code> (<code>EcuMDriverInitListOne</code> / Startup Phase) darf bei Nutzung dieses Musters nur <code>MemAcc_Init</code> eingetragen werden. Eine zusätzliche separate Initialisierung von <code>Mem_30_PFls_Init</code> oder <code>Mem_30_DFls_Init</code> durch den <code>EcuM</code> führt zu Doppelinitialisierungen und undefinierten Treiberzuständen.\n</li><li><strong>MemAcc-Konfigurationsvertrag:</strong> <code>MemAcc</code> benötigt in seinem Konfigurationsmodell (<code>MemAccMemDriver</code>) Funktionszeiger bzw. direkte Verknüpfungen zu den typspezifischen <code>Init</code>-APIs und Konfigurationsstrukturen der einzelnen <code>Mem</code>-Instanzen.\n</li><li><strong>Linker- &amp; Namensraum-Konventionen:</strong> Die Koexistenz mehrerer <code>Mem</code>-Treiber (hier <code>PFls</code> und <code>DFls</code>) erzwingt zwingend die Verwendung des AUTOSAR-Namensraumsamendments mit Vendor-ID und API-Infix (<code>Mem_&lt;VendorId&gt;_&lt;VendorApiInfix&gt;_Init</code>), um Namenskollisionen im Linker zu vermeiden.\n</li><li><strong>Startup-Timing &amp; Watchdog-Budget:</strong> Da alle konfigurierten <code>Mem</code>-Treiber synchron innerhalb von <code>MemAcc_Init()</code> abgearbeitet werden, kumuliert sich die Latenz (Hardware-Power-up, PLL-Locks, Flash-Zustandsprüfungen) direkt in den Startup-Pfad. Dies muss im Startup-Budget gegen Watchdog-Timeouts abgesichert werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-96242cf684fef771", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (ab Release R21-11), Spezifikation <code>AUTOSAR_CP_SWS_MemoryAccess</code> (<code>MemAcc</code>).\n</li><li><strong>Funktionale Einordnung:</strong> Kaskadierte Treiberinitialisierung im modernisierten AUTOSAR-Memory-Stack. Das Modul <code>MemAcc</code> kapselt den Zugriff auf hardwarenahe Speichertreiber (<code>Mem</code>-Treiber für Flash/EEPROM) und übernimmt bei dieser Architekturvariante die koordinierte Initialisierung der unterlagerten MCAL-Treiberinstanzen, wodurch der <code>EcuM</code> von der Einzelansteuerung entlastet wird.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Beteiligte Instanzen (<code>«module»</code>):</strong>\n<ul class=\"fig-list\"><li><code>:EcuM</code> (ECU State Manager, BSW System Services): Initiator der BSW-Initialisierungsphasen (z. B. StartOS/Post-OS bzw. EcuM Driver Init Block).\n</li><li><code>:MemAcc</code> (Memory Access Module, BSW Memory Abstraction/Service Layer): Zentraler Vermittler und Scheduler für Speicheraufträge; orchestriert die unterlagerten Treiber.\n</li><li><code>:Mem</code> (Memory Driver, BSW MCAL): Repräsentiert die konkreten Hardware-Treiberinstanzen gemäß <code>AUTOSAR_CP_SWS_MemoryDriver</code>. Im Diagramm differenziert über Vendor- und API-Infixes:\n<ul class=\"fig-list\"><li>Program Flash Driver: Infix <code>30_PFls</code> (Vendor-ID <code>30</code>, Program Flash).\n</li><li>Data Flash Driver: Infix <code>30_DFls</code> (Vendor-ID <code>30</code>, Data Flash).\n</li></ul>\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Signaturen:</strong>\n<ul class=\"fig-list\"><li><code>MemAcc_Init(const MemAcc_ConfigType* ConfigPtr)</code>: Globale Initialisierungs-API des <code>MemAcc</code>.\n</li><li><code>Mem_30_PFls_Init(const Mem_30_PFls_ConfigType* ConfigPtr)</code>: Treiber-Initialisierung für Program-Flash-Controller.\n</li><li><code>Mem_30_DFls_Init(const Mem_30_DFls_ConfigType* ConfigPtr)</code>: Treiber-Initialisierung für Data-Flash-Controller.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Trigger:</strong> <code>:EcuM</code> führt den synchronen Aufruf <code>MemAcc_Init()</code> aus.\n</li><li><strong>Kaskadierte Treiber-Initialisierung (sequenziell, blockierend):</strong>\n<ul class=\"fig-list\"><li><code>:MemAcc</code> ruft synchron <code>Mem_30_PFls_Init()</code> auf. Der Program-Flash-Treiber initialisiert Controller-Register, Verifikationszustände und Adressmappings; die Ausführung kehrt synchron zu <code>:MemAcc</code> zurück.\n</li><li><code>:MemAcc</code> ruft unmittelbar danach synchron <code>Mem_30_DFls_Init()</code> auf. Der Data-Flash-Treiber schließt die Hardwarekonfiguration ab und kehrt synchron zurück.\n</li></ul>\n</li><li><strong>Abschluss:</strong> Nach erfolgreicher Registrierung und Initialisierung aller im <code>MemAcc</code>-Konfigurationssatz referenzierten Treiber kehrt <code>MemAcc_Init()</code> zum <code>:EcuM</code> zurück.\n</li></ol>\n<ul class=\"fig-list\"><li><strong>Asynchronität / Callbacks:</strong> Keine asynchronen Pfade oder OS-Callbacks im gezeigten Pfad. Das Fehlerhandling (z. B. <code>MemAcc_Init()</code> bei ungültiger Konfiguration via <code>DET</code>) ist im Gutfall-Diagramm abstrahiert.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>EcuM-Konfiguration:</strong> In der BSW-Initialisierungstabelle des <code>EcuM</code> (<code>EcuMDriverInitListOne</code> / Startup Phase) darf bei Nutzung dieses Musters nur <code>MemAcc_Init</code> eingetragen werden. Eine zusätzliche separate Initialisierung von <code>Mem_30_PFls_Init</code> oder <code>Mem_30_DFls_Init</code> durch den <code>EcuM</code> führt zu Doppelinitialisierungen und undefinierten Treiberzuständen.\n</li><li><strong>MemAcc-Konfigurationsvertrag:</strong> <code>MemAcc</code> benötigt in seinem Konfigurationsmodell (<code>MemAccMemDriver</code>) Funktionszeiger bzw. direkte Verknüpfungen zu den typspezifischen <code>Init</code>-APIs und Konfigurationsstrukturen der einzelnen <code>Mem</code>-Instanzen.\n</li><li><strong>Linker- &amp; Namensraum-Konventionen:</strong> Die Koexistenz mehrerer <code>Mem</code>-Treiber (hier <code>PFls</code> und <code>DFls</code>) erzwingt zwingend die Verwendung des AUTOSAR-Namensraumsamendments mit Vendor-ID und API-Infix (<code>Mem_&lt;VendorId&gt;_&lt;VendorApiInfix&gt;_Init</code>), um Namenskollisionen im Linker zu vermeiden.\n</li><li><strong>Startup-Timing &amp; Watchdog-Budget:</strong> Da alle konfigurierten <code>Mem</code>-Treiber synchron innerhalb von <code>MemAcc_Init()</code> abgearbeitet werden, kumuliert sich die Latenz (Hardware-Power-up, PLL-Locks, Flash-Zustandsprüfungen) direkt in den Startup-Pfad. Dies muss im Startup-Budget gegen Watchdog-Timeouts abgesichert werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-7e94b1abe7e05b71", "to": "FIG-96242cf684fef771", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
